typedef unsigned long (*kfn)(unsigned long, unsigned long);

static double bench(kfn fn, unsigned long seed, unsigned long iters,
                    int reps, volatile unsigned long *sink) {
    double best = 1e18;
    for (int r = 0; r < reps; r++) {
        struct timespec a, b;
        clock_gettime(CLOCK_MONOTONIC, &a);
        unsigned long acc = fn(seed, iters);
        clock_gettime(CLOCK_MONOTONIC, &b);
        *sink ^= acc;
        double ns = (b.tv_sec - a.tv_sec) * 1e9 + (b.tv_nsec - a.tv_nsec);
        if (ns < best) best = ns;
    }
    return best / (double)iters;
}

int main(int argc, char **argv) {
    unsigned long seed = (unsigned long)argc * 2654435761UL + 1UL;
    int reps = 7;
    volatile unsigned long sink = 0;

    k_locals_clean_8(seed, 50000);
    k_locals_clean_32(seed, 50000);
    k_locals_clean_128(seed, 50000);
    k_locals_clean_512(seed, 50000);
    k_locals_clean_1024(seed, 50000);
    k_locals_clobber_8(seed, 50000);
    k_locals_clobber_32(seed, 50000);
    k_locals_clobber_128(seed, 50000);
    k_locals_clobber_512(seed, 50000);
    k_locals_clobber_1024(seed, 50000);
    k_global_clean_8(seed, 50000);
    k_global_clean_32(seed, 50000);
    k_global_clean_128(seed, 50000);
    k_global_clean_512(seed, 50000);
    k_global_clean_1024(seed, 50000);
    k_global_clobber_8(seed, 50000);
    k_global_clobber_32(seed, 50000);
    k_global_clobber_128(seed, 50000);
    k_global_clobber_512(seed, 50000);
    k_global_clobber_1024(seed, 50000);

    printf("reps=%d  ns per outer iteration (each = N mul-add updates); iters adapts to N\n", reps);
    printf("clean = no barrier ; clob = asm volatile(\"\":::\"memory\") once/iteration\n\n");
    printf("%5s | %10s | %9s %9s | %9s %9s | %7s %7s\n",
           "N", "iters", "loc_clean", "glb_clean", "loc_clob", "glb_clob", "g/l cln", "g/l clb");
    {
        unsigned long it = 200000000UL / 8UL;
        if (it > 20000000UL) it = 20000000UL;
        if (it < 200000UL)   it = 200000UL;
        double a = bench(k_locals_clean_8,   seed, it, reps, &sink);
        double b = bench(k_global_clean_8,   seed, it, reps, &sink);
        double c = bench(k_locals_clobber_8, seed, it, reps, &sink);
        double d = bench(k_global_clobber_8, seed, it, reps, &sink);
        printf("%5d | %10lu | %9.2f %9.2f | %9.2f %9.2f | %6.2fx %6.2fx\n",
               8, it, a, b, c, d, b / a, d / c);
    }
    {
        unsigned long it = 200000000UL / 32UL;
        if (it > 20000000UL) it = 20000000UL;
        if (it < 200000UL)   it = 200000UL;
        double a = bench(k_locals_clean_32,   seed, it, reps, &sink);
        double b = bench(k_global_clean_32,   seed, it, reps, &sink);
        double c = bench(k_locals_clobber_32, seed, it, reps, &sink);
        double d = bench(k_global_clobber_32, seed, it, reps, &sink);
        printf("%5d | %10lu | %9.2f %9.2f | %9.2f %9.2f | %6.2fx %6.2fx\n",
               32, it, a, b, c, d, b / a, d / c);
    }
    {
        unsigned long it = 200000000UL / 128UL;
        if (it > 20000000UL) it = 20000000UL;
        if (it < 200000UL)   it = 200000UL;
        double a = bench(k_locals_clean_128,   seed, it, reps, &sink);
        double b = bench(k_global_clean_128,   seed, it, reps, &sink);
        double c = bench(k_locals_clobber_128, seed, it, reps, &sink);
        double d = bench(k_global_clobber_128, seed, it, reps, &sink);
        printf("%5d | %10lu | %9.2f %9.2f | %9.2f %9.2f | %6.2fx %6.2fx\n",
               128, it, a, b, c, d, b / a, d / c);
    }
    {
        unsigned long it = 200000000UL / 512UL;
        if (it > 20000000UL) it = 20000000UL;
        if (it < 200000UL)   it = 200000UL;
        double a = bench(k_locals_clean_512,   seed, it, reps, &sink);
        double b = bench(k_global_clean_512,   seed, it, reps, &sink);
        double c = bench(k_locals_clobber_512, seed, it, reps, &sink);
        double d = bench(k_global_clobber_512, seed, it, reps, &sink);
        printf("%5d | %10lu | %9.2f %9.2f | %9.2f %9.2f | %6.2fx %6.2fx\n",
               512, it, a, b, c, d, b / a, d / c);
    }
    {
        unsigned long it = 200000000UL / 1024UL;
        if (it > 20000000UL) it = 20000000UL;
        if (it < 200000UL)   it = 200000UL;
        double a = bench(k_locals_clean_1024,   seed, it, reps, &sink);
        double b = bench(k_global_clean_1024,   seed, it, reps, &sink);
        double c = bench(k_locals_clobber_1024, seed, it, reps, &sink);
        double d = bench(k_global_clobber_1024, seed, it, reps, &sink);
        printf("%5d | %10lu | %9.2f %9.2f | %9.2f %9.2f | %6.2fx %6.2fx\n",
               1024, it, a, b, c, d, b / a, d / c);
    }
    printf("\nsink=%lu\n", sink);
    return 0;
}
